import React, { useState } from 'react';
import { trackEvent } from '../utils/analytics.js';

const AYUR_GREEN = '#6B8E23';
const AYUR_GOLD = '#D4AF37';
const AYUR_WARM = '#CD8B65';
const AYUR_LIGHT_BG = '#FEF7F0';

const Services = () => {
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);

  React.useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth < 768);
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const services = [
    { 
      icon: '🧘',
      title: 'Yoga & Meditation', 
      shortDesc: 'Transform Mind & Body',
      desc: 'Experience traditional Hatha and Ashtanga yoga with guided meditation sessions. Our certified yoga masters will help you achieve flexibility, strength, and inner peace through daily practice in the serene Himalayan atmosphere.',
      fullDesc: 'Daily 2-hour yoga sessions, pranayama techniques, and guided meditation to calm the mind and strengthen the body.',
      image: 'yoga.webp',
      benefits: ['Increased Flexibility', 'Mental Clarity', 'Stress Relief', 'Better Sleep'],
      stats: { duration: '7-21 Days', level: 'All Levels' }
    },
    { 
      icon: '💆',
      title: 'Panchakarma Treatment', 
      shortDesc: 'Complete Detoxification',
      desc: 'Complete detoxification and rejuvenation through authentic five-step Ayurvedic cleansing therapies. Our specialized treatments eliminate deep-seated toxins while balancing your doshas for lasting wellness.',
      fullDesc: 'Personalized five-phase Panchakarma program including Abhyanga, Swedana, Basti, Nasya, and Virechana treatments.',
      image: 'panchakarma.webp',
      benefits: ['Total Body Detox', 'Immune Boost', 'Digestive Health', 'Rejuvenation'],
      stats: { duration: '14-28 Days', level: 'Customized' }
    },
    { 
      icon: '💅',
      title: 'Therapeutic Massage', 
      shortDesc: 'Deep Healing & Relaxation',
      desc: 'Healing Ayurvedic massages using premium herbal oils tailored to your body type. Our expert therapists provide Abhyanga, Shirodhara, and Kizhi treatments for deep healing and complete rejuvenation.',
      fullDesc: 'Customized massage therapies with warm herbal oils, steam treatments, and specialized techniques for optimal healing.',
      image: 'massage.webp',
      benefits: ['Pain Relief', 'Muscle Relaxation', 'Improved Circulation', 'Skin Radiance'],
      stats: { duration: '3-14 Days', level: 'Relaxation & Healing' }
    },
    { 
      icon: '🩺',
      title: 'Ayurvedic Consultation', 
      shortDesc: 'Personalized Health Assessment',
      desc: 'One-on-one consultations with experienced Ayurvedic physicians who analyze your unique constitution. Receive a personalized treatment plan and lifestyle recommendations to balance your doshas permanently.',
      fullDesc: 'In-depth pulse diagnosis, constitutional assessment, and customized wellness protocols for long-term health.',
      image: 'consultation.webp',
      benefits: ['Dosha Analysis', 'Custom Protocol', 'Lifestyle Guidance', 'Ongoing Support'],
      stats: { duration: 'Single Session', level: 'Individual' }
    },
    { 
      icon: '🌿',
      title: 'Herbal Medicine & Supplements', 
      shortDesc: 'Nature\'s Healing Power',
      desc: 'Custom herbal formulations prepared fresh using traditional methods and pure Himalayan ingredients. Each medicine is crafted specifically for your needs with premium quality assurance.',
      fullDesc: 'Organic herbal preparations, Churnas, Tailams, and Ghritis prepared with ancient Ayurvedic techniques.',
      image: 'herbal.webp',
      benefits: ['100% Organic', 'Fresh Preparation', 'Proven Efficacy', 'Safe & Pure'],
      stats: { duration: 'Ongoing', level: 'Personalized' }
    },
  ];

  const handleBooking = (serviceTitle) => {
    trackEvent('service_booking_clicked', { service: serviceTitle });
    window.dispatchEvent(new CustomEvent('ayurveda:openBooking', { detail: { service: serviceTitle } }));
  };

  const handleLearnMore = (serviceTitle) => {
    trackEvent('service_learn_more_clicked', { service: serviceTitle });
  };

  return (
    <section id="services" style={{
      padding: isMobile ? '3rem 1rem' : '6rem 2rem',
      background: `linear-gradient(135deg, ${AYUR_LIGHT_BG} 0%, #FFFAF5 50%, #FAF3EB 100%)`,
      position: 'relative',
      fontFamily: "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif"
    }}>
      {/* Decorative Background Elements */}
      <div style={{
        position: 'absolute',
        top: '5%',
        right: '2%',
        width: '400px',
        height: '400px',
        background: `radial-gradient(circle, ${AYUR_WARM}08 0%, transparent 70%)`,
        borderRadius: '50%',
        pointerEvents: 'none'
      }}></div>
      <div style={{
        position: 'absolute',
        bottom: '10%',
        left: '5%',
        width: '350px',
        height: '350px',
        background: `radial-gradient(circle, ${AYUR_GOLD}08 0%, transparent 70%)`,
        borderRadius: '50%',
        pointerEvents: 'none'
      }}></div>

      <div style={{
        maxWidth: '1400px',
        margin: '0 auto',
        position: 'relative'
      }}>
        {/* Title Section */}
        <div style={{ 
          textAlign: 'center', 
          marginBottom: isMobile ? '2.5rem' : '4rem',
          position: 'relative'
        }}>
          <div style={{
            display: 'inline-block',
            padding: '0.6rem 1.5rem',
            background: `${AYUR_GOLD}15`,
            borderRadius: '30px',
            marginBottom: '1.5rem',
            border: `1.5px solid ${AYUR_GOLD}40`
          }}>
            <span style={{
              color: AYUR_GREEN,
              fontWeight: 700,
              fontSize: isMobile ? '0.8rem' : '0.9rem',
              letterSpacing: '0.5px'
            }}>✨ EXPLORE OUR PROGRAMS</span>
          </div>

          <h2 style={{
            fontSize: isMobile ? '2rem' : '3.5rem',
            fontWeight: 900,
            marginBottom: '1rem',
            letterSpacing: '-0.02em'
          }}>
            Ayurvedic <span style={{ background: `linear-gradient(135deg, ${AYUR_GREEN}, ${AYUR_WARM})`, backgroundClip: 'text', WebkitBackgroundClip: 'text', color: 'transparent' }}>Retreat Services</span>
          </h2>

          <p style={{
            fontSize: isMobile ? '1rem' : '1.25rem',
            color: '#6B7280',
            maxWidth: '700px',
            margin: '0 auto',
            lineHeight: '1.7',
            fontWeight: 400
          }}>
            Ancient healing wisdom meets modern comfort in the sacred land of Rishikesh. Each program is designed to restore balance and transform your life.
          </p>
        </div>

        {/* Primary Service Highlight */}
        <div style={{
          marginBottom: isMobile ? '3rem' : '5rem',
          padding: isMobile ? '2rem' : '3rem',
          background: 'white',
          borderRadius: '24px',
          border: `2px solid ${AYUR_GOLD}30`,
          boxShadow: `0 20px 60px ${AYUR_WARM}15`,
          position: 'relative'
        }}>
          <div style={{
            display: 'grid',
            gridTemplateColumns: isMobile ? '1fr' : '1.2fr 1fr',
            gap: isMobile ? '2rem' : '3rem',
            alignItems: 'center'
          }}>
            <div style={{ order: isMobile ? 2 : 1 }}>
              <div style={{
                display: 'inline-block',
                padding: '0.5rem 1.25rem',
                background: `${AYUR_WARM}15`,
                borderRadius: '20px',
                marginBottom: '1.5rem',
                border: `1px solid ${AYUR_WARM}30`
              }}>
                <span style={{ color: AYUR_WARM, fontWeight: 700, fontSize: '0.85rem' }}>⭐ MOST POPULAR</span>
              </div>

              <h3 style={{
                fontSize: isMobile ? '2rem' : '2.5rem',
                fontWeight: 900,
                color: AYUR_GREEN,
                marginBottom: '1rem'
              }}>
                {services[0].title}
              </h3>

              <p style={{
                fontSize: isMobile ? '1rem' : '1.15rem',
                color: '#6B7280',
                lineHeight: '1.8',
                marginBottom: '1.5rem'
              }}>
                {services[0].desc}
              </p>

              <div style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(2, 1fr)',
                gap: '1rem',
                marginBottom: '2rem'
              }}>
                {services[0].benefits.map((benefit, i) => (
                  <div key={i} style={{
                    padding: '0.75rem',
                    backgroundColor: `${AYUR_GREEN}08`,
                    borderRadius: '12px',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.5rem',
                    border: `1px solid ${AYUR_GREEN}20`
                  }}>
                    <span style={{ color: AYUR_WARM, fontSize: '1.2rem' }}>✓</span>
                    <span style={{ color: AYUR_GREEN, fontWeight: 600, fontSize: '0.9rem' }}>{benefit}</span>
                  </div>
                ))}
              </div>

              <div style={{
                display: 'flex',
                gap: '1rem',
                flexWrap: 'wrap',
                fontSize: '0.9rem'
              }}>
                <div style={{ fontWeight: 700, color: AYUR_WARM }}>📅 {services[0].stats.duration}</div>
                <div style={{ fontWeight: 700, color: AYUR_GREEN }}>🎯 {services[0].stats.level}</div>
              </div>
            </div>

            <div style={{ order: isMobile ? 1 : 2 }}>
              <div style={{
                position: 'relative',
                borderRadius: '20px',
                overflow: 'hidden',
                height: isMobile ? '280px' : '400px',
                boxShadow: `0 15px 50px ${AYUR_WARM}25`,
                background: `linear-gradient(135deg, ${AYUR_GREEN}, ${AYUR_WARM})`
              }}>
                <img 
                  src={services[0].image}
                  alt={services[0].title}
                  style={{
                    width: '100%',
                    height: '100%',
                    objectFit: 'cover',
                    objectPosition: 'center'
                  }}
                  onError={(e) => {
                    e.target.style.display = 'none';
                  }}
                />
              </div>
            </div>
          </div>

          <div style={{
            display: 'flex',
            gap: '1rem',
            marginTop: '2rem',
            flexWrap: 'wrap'
          }}>
            <button onClick={() => handleBooking(services[0].title)} style={{
              background: `linear-gradient(135deg, ${AYUR_GOLD}, ${AYUR_WARM})`,
              color: 'white',
              padding: isMobile ? '1rem 2rem' : '1.1rem 3rem',
              borderRadius: '30px',
              border: 'none',
              fontWeight: 800,
              fontSize: '1rem',
              cursor: 'pointer',
              transition: 'all 0.35s cubic-bezier(0.34, 1.56, 0.64, 1)',
              boxShadow: `0 15px 40px ${AYUR_WARM}35`,
              letterSpacing: '0.5px'
            }}
            onMouseEnter={(e) => {
              e.target.style.transform = 'translateY(-4px)';
              e.target.style.boxShadow = `0 25px 60px ${AYUR_WARM}45`;
            }}
            onMouseLeave={(e) => {
              e.target.style.transform = 'translateY(0)';
              e.target.style.boxShadow = `0 15px 40px ${AYUR_WARM}35`;
            }}>
              🎯 Book Now
            </button>

            <button onClick={() => handleLearnMore(services[0].title)} style={{
              background: 'transparent',
              color: AYUR_GREEN,
              padding: isMobile ? '1rem 2rem' : '1.1rem 3rem',
              borderRadius: '30px',
              border: `2.5px solid ${AYUR_GREEN}40`,
              fontWeight: 700,
              fontSize: '1rem',
              cursor: 'pointer',
              transition: 'all 0.3s ease',
              letterSpacing: '0.5px'
            }}
            onMouseEnter={(e) => {
              e.target.style.background = `${AYUR_GREEN}08`;
              e.target.style.borderColor = AYUR_GREEN;
              e.target.style.transform = 'translateY(-2px)';
            }}
            onMouseLeave={(e) => {
              e.target.style.background = 'transparent';
              e.target.style.borderColor = `${AYUR_GREEN}40`;
              e.target.style.transform = 'translateY(0)';
            }}>
              👉 Learn More
            </button>
          </div>
        </div>

        {/* Other Services Grid */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: isMobile ? '1fr' : 'repeat(2, 1fr)',
          gap: isMobile ? '1.5rem' : '2rem'
        }}>
          {services.slice(1).map((service, index) => (
            <div 
              key={index}
              style={{
                background: 'white',
                borderRadius: '20px',
                padding: isMobile ? '1.5rem' : '2rem',
                border: `1.5px solid ${AYUR_GOLD}25`,
                boxShadow: '0 8px 24px rgba(0, 0, 0, 0.06)',
                transition: 'all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)',
                cursor: 'pointer',
                position: 'relative',
                overflow: 'hidden'
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform = 'translateY(-8px)';
                e.currentTarget.style.boxShadow = `0 25px 50px ${AYUR_WARM}30`;
                e.currentTarget.style.borderColor = AYUR_WARM;
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'translateY(0)';
                e.currentTarget.style.boxShadow = '0 8px 24px rgba(0, 0, 0, 0.06)';
                e.currentTarget.style.borderColor = `${AYUR_GOLD}25`;
              }}
            >
              {/* Gradient accent bar */}
              <div style={{
                position: 'absolute',
                top: 0,
                left: 0,
                right: 0,
                height: '4px',
                background: `linear-gradient(90deg, ${AYUR_WARM}, ${AYUR_GOLD})`
              }}></div>

              <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>{service.icon}</div>

              <h4 style={{
                fontSize: isMobile ? '1.3rem' : '1.5rem',
                fontWeight: 800,
                color: AYUR_GREEN,
                marginBottom: '0.5rem'
              }}>
                {service.title}
              </h4>

              <p style={{
                fontSize: '0.95rem',
                color: AYUR_WARM,
                fontWeight: 700,
                marginBottom: '1rem',
                letterSpacing: '0.5px'
              }}>
                {service.shortDesc}
              </p>

              <p style={{
                fontSize: '0.95rem',
                color: '#6B7280',
                lineHeight: '1.6',
                marginBottom: '1.5rem'
              }}>
                {service.desc}
              </p>

              <div style={{
                display: 'flex',
                gap: '0.75rem',
                marginBottom: '1.5rem',
                flexWrap: 'wrap'
              }}>
                {service.benefits.slice(0, 2).map((benefit, i) => (
                  <span key={i} style={{
                    display: 'inline-block',
                    padding: '0.35rem 0.85rem',
                    background: `${AYUR_GREEN}12`,
                    borderRadius: '16px',
                    fontSize: '0.8rem',
                    fontWeight: 600,
                    color: AYUR_GREEN,
                    border: `1px solid ${AYUR_GREEN}25`
                  }}>
                    {benefit}
                  </span>
                ))}
              </div>

              <div style={{
                display: 'flex',
                gap: '1rem',
                justifyContent: 'space-between',
                alignItems: 'center',
                fontSize: '0.85rem',
                marginBottom: '1.5rem',
                color: '#6B7280'
              }}>
                <span>📅 {service.stats.duration}</span>
                <span>🎯 {service.stats.level}</span>
              </div>

              <div style={{
                display: 'flex',
                gap: '0.75rem'
              }}>
                <button onClick={() => handleBooking(service.title)} style={{
                  flex: 1,
                  background: `linear-gradient(135deg, ${AYUR_GOLD}, ${AYUR_WARM})`,
                  color: 'white',
                  padding: '0.75rem',
                  borderRadius: '20px',
                  border: 'none',
                  fontWeight: 700,
                  fontSize: '0.9rem',
                  cursor: 'pointer',
                  transition: 'all 0.3s ease'
                }}
                onMouseEnter={(e) => {
                  e.target.style.transform = 'scale(1.05)';
                }}
                onMouseLeave={(e) => {
                  e.target.style.transform = 'scale(1)';
                }}>
                  Book
                </button>

                <button onClick={() => handleLearnMore(service.title)} style={{
                  flex: 1,
                  background: `${AYUR_GREEN}10`,
                  color: AYUR_GREEN,
                  padding: '0.75rem',
                  borderRadius: '20px',
                  border: `1.5px solid ${AYUR_GREEN}30`,
                  fontWeight: 700,
                  fontSize: '0.9rem',
                  cursor: 'pointer',
                  transition: 'all 0.3s ease'
                }}
                onMouseEnter={(e) => {
                  e.target.style.background = AYUR_GREEN;
                  e.target.style.color = 'white';
                }}
                onMouseLeave={(e) => {
                  e.target.style.background = `${AYUR_GREEN}10`;
                  e.target.style.color = AYUR_GREEN;
                }}>
                  More
                </button>
              </div>
            </div>
          ))}
        </div>

        {/* CTA Section */}
        <div style={{
          marginTop: isMobile ? '3rem' : '5rem',
          padding: isMobile ? '2rem' : '3rem',
          background: `linear-gradient(135deg, ${AYUR_GREEN}15, ${AYUR_WARM}10)`,
          borderRadius: '24px',
          border: `2px dashed ${AYUR_WARM}40`,
          textAlign: 'center'
        }}>
          <h3 style={{
            fontSize: isMobile ? '1.5rem' : '2rem',
            fontWeight: 900,
            color: AYUR_GREEN,
            marginBottom: '1rem'
          }}>
            Can't Decide? Get Expert Guidance
          </h3>
          <p style={{
            fontSize: isMobile ? '0.95rem' : '1.1rem',
            color: '#6B7280',
            marginBottom: '2rem'
          }}>
            Our wellness consultants will help you choose the perfect program based on your health goals and preferences.
          </p>
          <button onClick={() => handleBooking('consultation')} style={{
            background: `linear-gradient(135deg, ${AYUR_WARM}, ${AYUR_GOLD})`,
            color: 'white',
            padding: isMobile ? '1rem 2.5rem' : '1.1rem 3.5rem',
            borderRadius: '30px',
            border: 'none',
            fontWeight: 800,
            fontSize: '1rem',
            cursor: 'pointer',
            transition: 'all 0.3s ease',
            boxShadow: `0 15px 40px ${AYUR_WARM}35`
          }}
          onMouseEnter={(e) => {
            e.target.style.transform = 'translateY(-4px)';
          }}
          onMouseLeave={(e) => {
            e.target.style.transform = 'translateY(0)';
          }}>
            📞 Schedule Free Consultation
          </button>
        </div>
      </div>

      <style>{`
        @media (max-width: 768px) {
          #services h2 {
            font-size: 2.2rem !important;
          }
          #services h3 {
            font-size: 1.5rem !important;
          }
        }

        @media (max-width: 640px) {
          #services {
            padding: 2rem 1rem !important;
          }
          #services h2 {
            font-size: 1.75rem !important;
          }
        }
      `}</style>
    </section>
  );
};

export default Services;
